"""Create and verify a model-only LittleFS image using the platform's filesystem tooling."""
import hashlib
import json
import re
from pathlib import Path

from littlefs import LittleFS

BLOCK_SIZE = 4096


def read_package(directory):
    """Verify every allowlisted package file before constructing a factory filesystem."""
    directory = Path(directory)
    manifest = json.loads((directory / "manifest.json").read_text(encoding="utf-8"))
    if not isinstance(manifest, list) or not manifest:
        raise ValueError("Invalid model manifest")
    files = {}
    for model in manifest:
        path = model.get("path", "")
        digest = model.get("sha256", "")
        size = model.get("size")
        if (not re.fullmatch(r"/inter_comms/model-[0-9a-f]{16}\.webp", path)
                or not re.fullmatch(r"[0-9a-f]{64}", digest)
                or not path.endswith(digest[:16] + ".webp")
                or type(size) is not int or not 0 < size <= 1024 * 1024
                or path in files):
            raise ValueError("Invalid model manifest entry")
        data = (directory / path.lstrip("/")).read_bytes()
        if len(data) != size or hashlib.sha256(data).hexdigest() != digest:
            raise ValueError("Model package is damaged: " + path)
        files[path] = data
    return files


def read_runtime_config(path):
    """Read the target SDK settings so host-generated images mount with the firmware's LittleFS version."""
    text = Path(path).read_text(encoding="utf-8")
    values = dict(re.findall(r"^#define\s+(CONFIG_LITTLEFS_\w+)\s+(\S+)", text, re.MULTILINE))
    fields = {"read_size": "READ_SIZE", "prog_size": "WRITE_SIZE", "cache_size": "CACHE_SIZE",
              "lookahead_size": "LOOKAHEAD_SIZE", "block_cycles": "BLOCK_CYCLES", "name_max": "OBJ_NAME_LEN"}
    try:
        config = {field: int(values["CONFIG_LITTLEFS_" + key], 0) for field, key in fields.items()}
    except (KeyError, ValueError) as error:
        raise ValueError("Missing or invalid LittleFS settings in target sdkconfig.h") from error
    versions = [minor for minor in (0, 1) if values.get(f"CONFIG_LITTLEFS_DISK_VERSION_2_{minor}") == "1"]
    if len(versions) != 1 or any(value <= 0 for value in config.values()):
        raise ValueError("Target must specify a supported LittleFS disk version and valid filesystem settings")
    config["disk_version"] = 0x00020000 + versions[0]
    return config


def filesystem(size, config):
    """Use the target runtime's on-disk version and I/O settings, rather than host-library defaults."""
    if size <= 0 or size % BLOCK_SIZE:
        raise ValueError("Filesystem partition size must be a positive multiple of 4096")
    return LittleFS(block_size=BLOCK_SIZE, block_count=size // BLOCK_SIZE, mount=False, **config)


def verify_filesystem(image, files, config):
    """Remount using the firmware's runtime configuration and verify every file's contents."""
    fs = filesystem(len(image), config)
    fs.context.buffer = bytearray(image)
    fs.mount()
    try:
        actual = {str(Path(root) / name).replace("\\", "/")
                  for root, _, names in fs.walk("/") for name in names}
        if actual != set(files):
            raise ValueError("Factory filesystem contains missing or unexpected files")
        for path, expected in files.items():
            with fs.open(path, "rb") as source:
                if source.read() != expected:
                    raise ValueError("Factory filesystem verification failed: " + path)
    finally:
        fs.unmount()


def build_filesystem(directory, size, config):
    """Populate a fresh filesystem with current models only; never include device configuration."""
    files = read_package(directory)
    fs = filesystem(size, config)
    fs.format()
    fs.mount()
    try:
        fs.mkdir("/inter_comms")
        for path, data in files.items():
            with fs.open(path, "wb") as target:
                target.write(data)
    finally:
        fs.unmount()
    image = bytes(fs.context.buffer)
    verify_filesystem(image, files, config)
    return image
